BodyContent.ST:
{region 'Generate Channel Addresses'}
(*------------------------------------------------------------------ 
            Convert the UINT module number to decimal text.
--------------------------------------------------------------------*)
    DIModule.DI0.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.0');
    DIModule.DI1.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.1');
    DIModule.DI2.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.2');
    DIModule.DI3.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.3');
    DIModule.DI4.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.4');
    DIModule.DI5.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.5');
    DIModule.DI6.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.6');
    DIModule.DI7.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.7');
    DIModule.DI8.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.8');
    DIModule.DI9.sChannel  := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.9');
    DIModule.DI10.sChannel := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.10');
    DIModule.DI11.sChannel := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.11');
    DIModule.DI12.sChannel := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.12');
    DIModule.DI13.sChannel := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.13');
    DIModule.DI14.sChannel := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.14');
    DIModule.DI15.sChannel := TO_STRING(DIModule.uiModuleNumber, 'DI{0:D}.15');
{endregion}


{region 'BYTE SWAP'}
(*------------------------------------------------------------------ 
                Apply optional byte swapping. 
--------------------------------------------------------------------*)
    IF xSwapBytes THEN
        wWorkingData.%B0 := DIModule.RawData.%B1;
        wWorkingData.%B1 := DIModule.RawData.%B0;
    ELSE
        wWorkingData := DIModule.RawData;
    END_IF;
{endregion}

{region 'Decode Raw Values'}
    DIModule.DI0.xRaw  := wWorkingData.%X0;
    DIModule.DI1.xRaw  := wWorkingData.%X1;
    DIModule.DI2.xRaw  := wWorkingData.%X2;
    DIModule.DI3.xRaw  := wWorkingData.%X3;
    DIModule.DI4.xRaw  := wWorkingData.%X4;
    DIModule.DI5.xRaw  := wWorkingData.%X5;
    DIModule.DI6.xRaw  := wWorkingData.%X6;
    DIModule.DI7.xRaw  := wWorkingData.%X7;
    DIModule.DI8.xRaw  := wWorkingData.%X8;
    DIModule.DI9.xRaw  := wWorkingData.%X9;
    DIModule.DI10.xRaw := wWorkingData.%X10;
    DIModule.DI11.xRaw := wWorkingData.%X11;
    DIModule.DI12.xRaw := wWorkingData.%X12;
    DIModule.DI13.xRaw := wWorkingData.%X13;
    DIModule.DI14.xRaw := wWorkingData.%X14;
    DIModule.DI15.xRaw := wWorkingData.%X15;
{endregion}

{region 'Bit Forcing'}
    DIModule.DI0.xVal       :=      (DIModule.DI0.xRaw OR DIModule.DI0.xForceTrue)
                            AND     NOT DIModule.DI0.xForceFalse;
    DIModule.DI1.xVal       :=      (DIModule.DI1.xRaw OR DIModule.DI1.xForceTrue)
                            AND     NOT DIModule.DI1.xForceFalse;
    DIModule.DI2.xVal       :=      (DIModule.DI2.xRaw OR DIModule.DI2.xForceTrue)
                            AND     NOT DIModule.DI2.xForceFalse;
    DIModule.DI3.xVal       :=      (DIModule.DI3.xRaw OR DIModule.DI3.xForceTrue)
                            AND     NOT DIModule.DI3.xForceFalse;
    DIModule.DI4.xVal       :=      (DIModule.DI4.xRaw OR DIModule.DI4.xForceTrue)
                            AND     NOT DIModule.DI4.xForceFalse;
    DIModule.DI5.xVal       :=      (DIModule.DI5.xRaw OR DIModule.DI5.xForceTrue)
                            AND     NOT DIModule.DI5.xForceFalse;
    DIModule.DI6.xVal       :=      (DIModule.DI6.xRaw OR DIModule.DI6.xForceTrue)
                            AND     NOT DIModule.DI6.xForceFalse;  
    DIModule.DI7.xVal       :=      (DIModule.DI7.xRaw OR DIModule.DI7.xForceTrue)
                            AND     NOT DIModule.DI7.xForceFalse;
    DIModule.DI8.xVal       :=      (DIModule.DI8.xRaw OR DIModule.DI8.xForceTrue)
                            AND     NOT DIModule.DI8.xForceFalse;
    DIModule.DI9.xVal       :=      (DIModule.DI9.xRaw OR DIModule.DI9.xForceTrue)
                            AND     NOT DIModule.DI9.xForceFalse;
    DIModule.DI10.xVal       :=      (DIModule.DI10.xRaw OR DIModule.DI10.xForceTrue)
                            AND     NOT DIModule.DI10.xForceFalse;
    DIModule.DI11.xVal       :=      (DIModule.DI11.xRaw OR DIModule.DI11.xForceTrue)
                            AND     NOT DIModule.DI11.xForceFalse;
    DIModule.DI12.xVal       :=      (DIModule.DI12.xRaw OR DIModule.DI12.xForceTrue)
                            AND     NOT DIModule.DI12.xForceFalse;
    DIModule.DI13.xVal       :=      (DIModule.DI13.xRaw OR DIModule.DI13.xForceTrue)
                            AND     NOT DIModule.DI13.xForceFalse;                            
    DIModule.DI14.xVal       :=      (DIModule.DI14.xRaw OR DIModule.DI14.xForceTrue)
                            AND     NOT DIModule.DI14.xForceFalse;
    DIModule.DI15.xVal       :=      (DIModule.DI15.xRaw OR DIModule.DI15.xForceTrue)
                            AND     NOT DIModule.DI15.xForceFalse;                            
{endregion}

{region 'Publish Values'}
    DIModule.ProcessedData          :=      wWorkingData;
    DIModule.ProcessedData.%X0      :=      DIModule.DI0.xVal;
    DIModule.ProcessedData.%X1      :=      DIModule.DI1.xVal;
    DIModule.ProcessedData.%X2      :=      DIModule.DI2.xVal;
    DIModule.ProcessedData.%X3      :=      DIModule.DI3.xVal;
    DIModule.ProcessedData.%X4      :=      DIModule.DI4.xVal;
    DIModule.ProcessedData.%X5      :=      DIModule.DI5.xVal;
    DIModule.ProcessedData.%X6      :=      DIModule.DI6.xVal;
    DIModule.ProcessedData.%X7      :=      DIModule.DI7.xVal;
    DIModule.ProcessedData.%X8      :=      DIModule.DI8.xVal;
    DIModule.ProcessedData.%X9      :=      DIModule.DI9.xVal;
    DIModule.ProcessedData.%X10     :=      DIModule.DI10.xVal;
    DIModule.ProcessedData.%X11     :=      DIModule.DI11.xVal;
    DIModule.ProcessedData.%X12     :=      DIModule.DI12.xVal;
    DIModule.ProcessedData.%X13     :=      DIModule.DI13.xVal;
    DIModule.ProcessedData.%X14     :=      DIModule.DI14.xVal;
    DIModule.ProcessedData.%X15     :=      DIModule.DI15.xVal;
{endregion}
